   108  int dynsec_clients__config_load(struct dynsec__data *data, cJSON *tree)
   109  {
   110          cJSON *j_clients, *j_client, *jtmp, *j_roles, *j_role;
   111          cJSON *j_salt, *j_password, *j_iterations;
   112          struct dynsec__client *client;
   113          struct dynsec__role *role;
   114          unsigned char *buf;
   115          unsigned int buf_len;
   116          int priority;
   117          int iterations;
   118          size_t username_len;
   119
   120          j_clients = cJSON_GetObjectItem(tree, "clients");
   121          if(j_clients == NULL){
   122                  return 0;
   123          }
   124
   125          if(cJSON_IsArray(j_clients) == false){
   126                  return 1;
   127          }
   128
   129          cJSON_ArrayForEach(j_client, j_clients){
   130                  if(cJSON_IsObject(j_client) == true){
   131                          /* Username */
   132                          jtmp = cJSON_GetObjectItem(j_client, "username");
   133                          if(jtmp == NULL || !cJSON_IsString(jtmp)){
   134                                  continue;
   135                          }
   136                          username_len = strlen(jtmp->valuestring);
   137                          if(username_len == 0){
   138                                  continue;
   139                          }
   140
   141                          client = mosquitto_calloc(1, sizeof(struct dynsec__client) + username_len + 1);
   142                          if(client == NULL){
   143                                  return MOSQ_ERR_NOMEM;
   144                          }
   145                          strncpy(client->username, jtmp->valuestring, username_len);
   146
   147                          jtmp = cJSON_GetObjectItem(j_client, "disabled");
   148                          if(jtmp && cJSON_IsBool(jtmp)){
   149                                  client->disabled = cJSON_IsTrue(jtmp);
   150                          }
   151
   152                          /* Salt */
   153                          j_salt = cJSON_GetObjectItem(j_client, "salt");
   154                          j_password = cJSON_GetObjectItem(j_client, "password");
   155                          j_iterations = cJSON_GetObjectItem(j_client, "iterations");
   156
   157                          if(j_salt && cJSON_IsString(j_salt)
   158                                          && j_password && cJSON_IsString(j_password)
   159                                          && j_iterations && cJSON_IsNumber(j_iterations)){
   160
   161                                  iterations = (int)j_iterations->valuedouble;
   162                                  if(iterations < 1){
   163                                          mosquitto_free(client);
   164                                          continue;
   165                                  }else{
   166                                          client->pw.iterations = iterations;
   167                                  }
   168
   169                                  if(base64__decode(j_salt->valuestring, &buf, &buf_len) != MOSQ_ERR_SUCCESS
   170                                                  || buf_len > sizeof(client->pw.salt)){
   171
   172                                          mosquitto_free(client);
   173                                          continue;
   174                                  }
   175                                  memcpy(client->pw.salt, buf, (size_t)buf_len);
   176                                  client->pw.salt_len = (size_t)buf_len;
   177                                  mosquitto_free(buf);
   178
   179                                  if(base64__decode(j_password->valuestring, &buf, &buf_len) != MOSQ_ERR_SUCCESS
   180                                                  || buf_len != sizeof(client->pw.password_hash)){
   181
   182                                          mosquitto_free(client);
   183                                          continue;
   184                                  }
   185                                  memcpy(client->pw.password_hash, buf, (size_t)buf_len);
   186                                  mosquitto_free(buf);
   187                                  client->pw.valid = true;
   188                          }else{
   189                                  client->pw.valid = false;
   190                          }
   191
   192                          /* Client id */
   193                          jtmp = cJSON_GetObjectItem(j_client, "clientid");
   194                          if(jtmp != NULL && cJSON_IsString(jtmp)){
   195                                  client->clientid = mosquitto_strdup(jtmp->valuestring);
   196                                  if(client->clientid == NULL){
   197                                          mosquitto_free(client);
   198                                          continue;
   199                                  }
   200                          }
   201
   202                          /* Text name */
   203                          jtmp = cJSON_GetObjectItem(j_client, "textname");
   204                          if(jtmp != NULL && cJSON_IsString(jtmp)){
   205                                  client->text_name = mosquitto_strdup(jtmp->valuestring);
   206                                  if(client->text_name == NULL){
   207                                          mosquitto_free(client->clientid);
   208                                          mosquitto_free(client);
   209                                          continue;
   210                                  }
   211                          }
   212
   213                          /* Text description */
   214                          jtmp = cJSON_GetObjectItem(j_client, "textdescription");
   215                          if(jtmp != NULL && cJSON_IsString(jtmp)){
   216                                  client->text_description = mosquitto_strdup(jtmp->valuestring);
   217                                  if(client->text_description == NULL){
   218                                          mosquitto_free(client->text_name);
   219                                          mosquitto_free(client->clientid);
   220                                          mosquitto_free(client);
   221                                          continue;
   222                                  }
   223                          }
   224
   225                          /* Roles */
   226                          j_roles = cJSON_GetObjectItem(j_client, "roles");
   227                          if(j_roles && cJSON_IsArray(j_roles)){
   228                                  cJSON_ArrayForEach(j_role, j_roles){
   229                                          if(cJSON_IsObject(j_role)){
   230                                                  jtmp = cJSON_GetObjectItem(j_role, "rolename");
   231                                                  if(jtmp && cJSON_IsString(jtmp)){
   232                                                          json_get_int(j_role, "priority", &priority, true, -1);
   233                                                          role = dynsec_roles__find(data, jtmp->valuestring);
   234                                                          dynsec_rolelist__client_add(client, role, priority);
   235                                                  }
   236                                          }
   237                                  }
   238                          }
   239
   240                          HASH_ADD(hh, data->clients, username, username_len, client);
   241                  }
   242          }
   243          HASH_SORT(data->clients, client_cmp);
   244
   245          return 0;
   246  }
