    97  int dynsec__config_load(struct dynsec__data *data)
    98  {
    99          FILE *fptr;
   100          long flen_l;
   101          size_t flen;
   102          char *json_str;
   103          int rc;
   104
   105          /* Load from file */
   106          fptr = fopen(data->config_file, "rb");
   107          if(fptr == NULL){
   108                  /* Attempt to initialise a new config file */
   109                  if(dynsec__config_init(data) == MOSQ_ERR_SUCCESS){
   110                          /* If it works, try to open the file again */
   111                          fptr = fopen(data->config_file, "rb");
   112                  }
   113
   114                  if(fptr == NULL){
   115                          mosquitto_log_printf(MOSQ_LOG_ERR,
   116                                          "Error loading Dynamic security plugin config: File is not readable - check permissions.");
   117                          return MOSQ_ERR_UNKNOWN;
   118                  }
   119          }
   120
   121          fseek(fptr, 0, SEEK_END);
   122          flen_l = ftell(fptr);
   123          if(flen_l < 0){
   124                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error loading Dynamic security plugin config: %s", strerror(errno));
   125                  fclose(fptr);
   126                  return 1;
   127          }else if(flen_l == 0){
   128                  fclose(fptr);
   129                  return 0;
   130          }
   131          flen = (size_t)flen_l;
   132          fseek(fptr, 0, SEEK_SET);
   133          json_str = mosquitto_calloc(flen+1, sizeof(char));
   134          if(json_str == NULL){
   135                  mosquitto_log_printf(MOSQ_LOG_ERR, "Error: Out of memory.");
   136                  fclose(fptr);
   137                  return 1;
   138          }
   139          if(fread(json_str, 1, flen, fptr) != flen){
   140                  mosquitto_log_printf(MOSQ_LOG_WARNING, "Error loading Dynamic security plugin config: Unable to read file contents.\n");
   141                  mosquitto_free(json_str);
   142                  fclose(fptr);
   143                  return 1;
   144          }
   145          fclose(fptr);
   146
   147          rc = dynsec__config_from_json(data, json_str);
   148          free(json_str);
   149          return rc;
   150  }
