   189  int dynsec_groups__config_load(struct dynsec__data *data, cJSON *tree)
   190  {
   191          cJSON *j_groups, *j_group;
   192          cJSON *j_clientlist, *j_client, *j_username;
   193          cJSON *j_roles, *j_role, *j_rolename;
