   201          j_groups = cJSON_GetObjectItem(tree, "groups");
   202          if(j_groups == NULL){
   203                  return 0;
   204          }
   205
   206          if(cJSON_IsArray(j_groups) == false){
   207                  return 1;
   208          }
   209
   210          cJSON_ArrayForEach(j_group, j_groups){
   211                  if(cJSON_IsObject(j_group) == true){
   212                          /* Group name */
   213                          if(json_get_string(j_group, "groupname", &str, false) != MOSQ_ERR_SUCCESS){
   214                                  continue;
   215                          }
   216                          groupname_len = strlen(str);
   217                          if(groupname_len == 0){
   218                                  continue;
   219                          }
   220
   221                          group = mosquitto_calloc(1, sizeof(struct dynsec__group) + groupname_len + 1);
   222                          if(group == NULL){
   223                                  return MOSQ_ERR_NOMEM;
   224                          }
   225                          strncpy(group->groupname, str, groupname_len+1);
   226
   227                          /* Text name */
   228                          if(json_get_string(j_group, "textname", &str, false) == MOSQ_ERR_SUCCESS){
   229                                  if(str){
   230                                          group->text_name = strdup(str);
   231                                          if(group->text_name == NULL){
   232                                                  mosquitto_free(group);
   233                                                  continue;
   234                                          }
   235                                  }
   236                          }
   237
   238                          /* Text description */
   239                          if(json_get_string(j_group, "textdescription", &str, false) == MOSQ_ERR_SUCCESS){
   240                                  if(str){
   241                                          group->text_description = strdup(str);
   242                                          if(group->text_description == NULL){
   243                                                  mosquitto_free(group->text_name);
   244                                                  mosquitto_free(group);
   245                                                  continue;
   246                                          }
   247                                  }
   248                          }
   249
   250                          /* Roles */
   251                          j_roles = cJSON_GetObjectItem(j_group, "roles");
   252                          if(j_roles && cJSON_IsArray(j_roles)){
   253                                  cJSON_ArrayForEach(j_role, j_roles){
   254                                          if(cJSON_IsObject(j_role)){
   255                                                  j_rolename = cJSON_GetObjectItem(j_role, "rolename");
   256                                                  if(j_rolename && cJSON_IsString(j_rolename)){
   257                                                          json_get_int(j_role, "priority", &priority, true, -1);
   258                                                          role = dynsec_roles__find(data, j_rolename->valuestring);
   259                                                          dynsec_rolelist__group_add(group, role, priority);
   260                                                  }
   261                                          }
   262                                  }
   263                          }
   264
   265                          /* This must go before clients are loaded, otherwise the group won't be found */
   266                          HASH_ADD(hh, data->groups, groupname, groupname_len, group);
   267
   268                          /* Clients */
   269                          j_clientlist = cJSON_GetObjectItem(j_group, "clients");
   270                          if(j_clientlist && cJSON_IsArray(j_clientlist)){
   271                                  cJSON_ArrayForEach(j_client, j_clientlist){
   272                                          if(cJSON_IsObject(j_client)){
   273                                                  j_username = cJSON_GetObjectItem(j_client, "username");
   274                                                  if(j_username && cJSON_IsString(j_username)){
   275                                                          json_get_int(j_client, "priority", &priority, true, -1);
   276                                                          dynsec_groups__add_client(data, j_username->valuestring, group->groupname, priority, false);
   277                                                  }
   278                                          }
   279                                  }
   280                          }
   281                  }
   282          }
   283          HASH_SORT(data->groups, group_cmp);
   284
   285          j_group = cJSON_GetObjectItem(tree, "anonymousGroup");
   286          if(j_group && cJSON_IsString(j_group)){
   287                  data->anonymous_group = dynsec_groups__find(data, j_group->valuestring);
   288          }
   289
   290          return 0;

